<?php
namespace App\Services\Admin;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class EcosystemControlCenterService{
public function integrations(Request$r):array{$q=$this->integrationQuery($r);$total=(clone$q)->count();$count=fn($c,$v)=>(clone$q)->where($c,$v)->count();$providers=(clone$q)->selectRaw('i.provider,COUNT(*) count,SUM(CASE WHEN i.risk_level IN (\'high\',\'critical\') THEN 1 ELSE 0 END) critical')->groupBy('i.provider')->get();return['summary'=>['registered'=>$total,'active'=>$count('i.status','active'),'healthy'=>$count('i.health_status','healthy'),'degraded'=>$count('i.health_status','degraded'),'failed'=>$count('i.health_status','failed'),'notEvaluated'=>$count('i.health_status','not_evaluated'),'highRisk'=>$count('i.risk_level','high')+$count('i.risk_level','critical')],'health'=>['score'=>null,'status'=>$total?'not_evaluated':'not_evaluated','reason'=>'No approved numeric integration-health formula exists.'],'providers'=>$providers,'governance'=>['openAlerts'=>DB::table('ecosystem_module_alerts')->where('status','open')->count(),'openRisks'=>DB::table('ecosystem_module_risks')->where('status','open')->count(),'certificatesExpiring'=>(clone$q)->whereBetween('i.certificate_expires_at',[now(),now()->addDays(30)])->count()],'telemetry'=>['available'=>DB::table('ecosystem_integration_health_checks')->exists(),'message'=>DB::table('ecosystem_integration_health_checks')->exists()?'Recorded integration checks available.':'Integration telemetry unavailable.'],'activity'=>$this->integrationActivity(),'permissions'=>$this->permissions($r),'generatedAt'=>now()->toIso8601String()];}
public function integrationList(Request$r){$v=$r->validate(['sort'=>['nullable','in:name,provider,status,health_status,updated_at'],'direction'=>['nullable','in:asc,desc'],'per_page'=>['nullable','integer','between:1,100']]);return$this->integrationQuery($r)->select('i.id','i.uuid','i.name','i.provider','i.category','i.integration_type','i.environment','i.status','i.health_status','i.auth_type','i.credential_reference','i.endpoint_reference','i.owner','i.risk_level','i.compliance_status','i.latency_ms','i.timeout_ms','i.retry_limit','i.sla_target_ms','i.credential_rotated_at','i.certificate_expires_at','i.last_checked_at','i.lock_version','m.name as module_name')->orderBy('i.'.($v['sort']??'updated_at'),$v['direction']??'desc')->paginate($v['per_page']??20);}
public function registerIntegration(array$d,Request$r):object{return DB::transaction(function()use($d,$r){$id=DB::table('ecosystem_module_integrations')->insertGetId([...$d,'uuid'=>(string)Str::uuid(),'status'=>'not_configured','health_status'=>'not_evaluated','risk_level'=>'unknown','compliance_status'=>'not_evaluated','lock_version'=>1,'created_at'=>now(),'updated_at'=>now()]);$this->integrationAudit($id,$r,'registered',null,$this->safe($d));return DB::table('ecosystem_module_integrations')->find($id);});}
public function updateIntegration(int$id,array$d,Request$r):object{return DB::transaction(function()use($id,$d,$r){$row=DB::table('ecosystem_module_integrations')->lockForUpdate()->find($id);abort_unless($row,404);abort_if((int)$d['lock_version']!==(int)$row->lock_version,409,'Integration was changed by another administrator.');unset($d['lock_version']);DB::table('ecosystem_module_integrations')->where('id',$id)->update([...$d,'lock_version'=>$row->lock_version+1,'updated_at'=>now()]);$this->integrationAudit($id,$r,'updated',$this->safe((array)$row),$this->safe($d));return DB::table('ecosystem_module_integrations')->find($id);});}
public function governance(Request$r):array{$pending=DB::table('ecosystem_access_requests')->where('status','pending');$temp=DB::table('ecosystem_temporary_access')->where('status','active')->where('starts_at','<=',now())->where('expires_at','>',now());$sod=$this->sodConflicts();return['summary'=>['humanIdentities'=>DB::table('users')->count(),'servicePrincipals'=>0,'activeRoles'=>DB::table('roles')->where('status','active')->count(),'activePermissions'=>DB::table('permissions')->where('status','active')->count(),'policies'=>DB::table('ecosystem_access_policies')->count(),'pendingRequests'=>(clone$pending)->count(),'temporaryAccess'=>(clone$temp)->count(),'sodConflicts'=>count($sod)],'health'=>['score'=>null,'status'=>count($sod)?'warning':'not_evaluated','reason'=>'No approved numeric governance-health formula exists.'],'identities'=>$this->identities($r),'policies'=>DB::table('ecosystem_access_policies')->latest()->limit(20)->get(),'roles'=>DB::table('roles')->where('status','active')->get(),'permissionsRegistry'=>DB::table('permissions')->where('status','active')->get(),'effectivePermissions'=>$this->effectivePermissions(),'requests'=>DB::table('ecosystem_access_requests as ar')->join('users as u','u.id','=','ar.target_user_id')->leftJoin('roles as ro','ro.id','=','ar.role_id')->leftJoin('permissions as p','p.id','=','ar.permission_id')->latest('ar.created_at')->limit(20)->get(['ar.*','u.name as identity','ro.display_name as role_name','p.display_name as permission_name']),'temporaryAccess'=>(clone$temp)->get(),'certifications'=>DB::table('ecosystem_access_certifications')->latest()->get(),'sodConflicts'=>$sod,'activity'=>DB::table('ecosystem_governance_audits as a')->leftJoin('users as u','u.id','=','a.actor_id')->latest('a.created_at')->limit(15)->get(['a.*','u.name as actor']),'permissions'=>$this->permissions($r),'generatedAt'=>now()->toIso8601String()];}
public function createRequest(array$d,Request$r):object{return DB::transaction(function()use($d,$r){$id=DB::table('ecosystem_access_requests')->insertGetId([...$d,'uuid'=>(string)Str::uuid(),'requester_id'=>$r->user()->id,'status'=>'pending','lock_version'=>1,'created_at'=>now(),'updated_at'=>now()]);$this->govAudit('access_request',$id,$r,'created',null,$d);return DB::table('ecosystem_access_requests')->find($id);});}
public function decideRequest(int$id,string$decision,array$d,Request$r):object{return DB::transaction(function()use($id,$decision,$d,$r){$x=DB::table('ecosystem_access_requests')->lockForUpdate()->find($id);abort_unless($x,404);abort_unless($x->status==='pending',409,'Access request was already decided.');abort_if((int)$d['lock_version']!==(int)$x->lock_version,409,'Access request changed.');$status=$decision==='approve'?'approved':'rejected';DB::table('ecosystem_access_requests')->where('id',$id)->update(['status'=>$status,'decided_by'=>$r->user()->id,'decision_reason'=>$d['reason'],'decided_at'=>now(),'lock_version'=>$x->lock_version+1,'updated_at'=>now()]);if($status==='approved'){if(!empty($d['expires_at']))DB::table('ecosystem_temporary_access')->insert(['access_request_id'=>$id,'user_id'=>$x->target_user_id,'role_id'=>$x->role_id,'permission_id'=>$x->permission_id,'starts_at'=>now(),'expires_at'=>$d['expires_at'],'status'=>'active','approved_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);elseif($x->role_id){$role=DB::table('roles')->find($x->role_id);abort_unless($role,422,'Requested role no longer exists.');DB::table('users')->where('id',$x->target_user_id)->update(['role'=>$role->name,'updated_at'=>now()]);}}$this->govAudit('access_request',$id,$r,$status,(array)$x,['status'=>$status,'expires_at'=>$d['expires_at']??null],$d['reason']);return DB::table('ecosystem_access_requests')->find($id);});}
public function auditDashboard(Request$r):array{$aq=$this->auditQuery($r);$records=(clone$aq)->latest('activity_log.created_at')->paginate((int)$r->input('per_page',20));$records->getCollection()->transform(function($row){$row->properties=$this->safeJson($row->properties);return$row;});$reports=DB::table('report_runs as rr')->join('report_definitions as rd','rd.id','=','rr.report_definition_id')->where('rd.report_type','ecosystem');$exports=DB::table('report_exports as e')->join('report_runs as rr','rr.id','=','e.report_run_id')->join('report_definitions as rd','rd.id','=','rr.report_definition_id')->where('rd.report_type','ecosystem');return['summary'=>['auditRecords'=>(clone$aq)->count(),'reports'=>(clone$reports)->count(),'exports'=>(clone$exports)->count(),'scheduledReports'=>DB::table('ecosystem_report_schedules')->where('status','active')->count(),'exceptions'=>DB::table('ecosystem_audit_exceptions')->where('status','open')->count(),'failedExports'=>(clone$exports)->where('e.status','failed')->count(),'evidencePackages'=>DB::table('ecosystem_evidence_packages')->count()],'health'=>['score'=>null,'status'=>'not_evaluated','reason'=>'Cryptographic audit-integrity verification is not configured.'],'records'=>$records,'reports'=>(clone$reports)->latest('rr.created_at')->limit(20)->get(['rr.*','rd.name']),'exports'=>(clone$exports)->latest('e.created_at')->limit(20)->get(['e.*','rd.name']),'schedules'=>DB::table('ecosystem_report_schedules as s')->join('report_definitions as rd','rd.id','=','s.report_definition_id')->get(['s.*','rd.name']),'evidence'=>DB::table('ecosystem_evidence_packages')->latest()->get(),'exceptions'=>DB::table('ecosystem_audit_exceptions')->where('status','open')->latest()->get(),'permissions'=>$this->permissions($r),'generatedAt'=>now()->toIso8601String()];}
public function generateReport(array$d,Request$r):object{return DB::transaction(function()use($d,$r){$def=DB::table('report_definitions')->where('slug',$d['slug'])->first();if(!$def){$id=DB::table('report_definitions')->insertGetId(['uuid'=>(string)Str::uuid(),'user_id'=>$r->user()->id,'name'=>$d['name'],'slug'=>$d['slug'],'report_type'=>'ecosystem','status'=>'active','created_at'=>now(),'updated_at'=>now()]);$def=DB::table('report_definitions')->find($id);}$id=DB::table('report_runs')->insertGetId(['uuid'=>(string)Str::uuid(),'report_definition_id'=>$def->id,'user_id'=>$r->user()->id,'report_type'=>'ecosystem','status'=>'completed','parameters'=>json_encode($d['filters']??[]),'result_summary'=>json_encode(['auditRecords'=>$this->auditQuery($r)->count()]),'started_at'=>now(),'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);activity('ecosystem')->causedBy($r->user())->withProperties(['report_run_id'=>$id])->log('ecosystem_report.generated');return DB::table('report_runs')->find($id);});}
private function integrationQuery(Request$r){$q=DB::table('ecosystem_module_integrations as i')->join('ecosystem_modules as m','m.id','=','i.ecosystem_module_id');if($r->filled('search')){$s='%'.$r->search.'%';$q->where(fn($x)=>$x->where('i.name','like',$s)->orWhere('i.provider','like',$s)->orWhere('m.name','like',$s));}foreach(['status'=>'i.status','health'=>'i.health_status','environment'=>'i.environment','provider'=>'i.provider','type'=>'i.integration_type']as$k=>$c)if($r->filled($k))$q->where($c,$r->$k);return$q;}
private function identities(Request$r){$q=DB::table('users')->select('id','name','email','role','last_login_at','security_status','created_at');if($r->filled('search')){$s='%'.$r->search.'%';$q->where(fn($x)=>$x->where('name','like',$s)->orWhere('email','like',$s));}return$q->paginate((int)$r->input('per_page',20));}
private function effectivePermissions(){$permanent=DB::table('users as u')->join('roles as r','r.name','=','u.role')->join('permission_role as pr','pr.role_id','=','r.id')->join('permissions as p','p.id','=','pr.permission_id')->where('r.status','active')->where('pr.status','active')->where('p.status','active')->get(['u.id as user_id','u.name as identity','r.display_name as role','p.display_name as permission','p.name as permission_key','p.group as scope'])->map(fn($x)=>(object)[...(array)$x,'source'=>'role']);$temporary=DB::table('ecosystem_temporary_access as ta')->join('users as u','u.id','=','ta.user_id')->leftJoin('roles as r','r.id','=','ta.role_id')->leftJoin('permission_role as pr','pr.role_id','=','r.id')->leftJoin('permissions as rp','rp.id','=','pr.permission_id')->leftJoin('permissions as dp','dp.id','=','ta.permission_id')->where('ta.status','active')->where('ta.starts_at','<=',now())->where('ta.expires_at','>',now())->where(fn($q)=>$q->whereNotNull('rp.id')->orWhereNotNull('dp.id'))->get(['u.id as user_id','u.name as identity','r.display_name as role','rp.display_name as role_permission','rp.name as role_permission_key','rp.group as role_scope','dp.display_name as direct_permission','dp.name as direct_permission_key','dp.group as direct_scope'])->map(fn($x)=>(object)['user_id'=>$x->user_id,'identity'=>$x->identity,'role'=>$x->role??'Temporary grant','permission'=>$x->direct_permission??$x->role_permission,'permission_key'=>$x->direct_permission_key??$x->role_permission_key,'scope'=>$x->direct_scope??$x->role_scope,'source'=>'temporary']);return$permanent->concat($temporary)->unique(fn($x)=>$x->user_id.'|'.$x->permission_key)->values();}
private function sodConflicts():array{$effective=$this->effectivePermissions()->groupBy('user_id');$rules=DB::table('ecosystem_sod_rules as s')->join('permissions as a','a.id','=','s.permission_a_id')->join('permissions as b','b.id','=','s.permission_b_id')->where('s.status','active')->get(['s.id','s.name','s.severity','a.name as permission_a','b.name as permission_b']);$out=[];foreach($effective as$user=>$perms){$keys=$perms->pluck('permission_key');foreach($rules as$rule)if($keys->contains($rule->permission_a)&&$keys->contains($rule->permission_b))$out[]=['userId'=>$user,'identity'=>$perms->first()->identity,'rule'=>$rule->name,'severity'=>$rule->severity,'permissions'=>[$rule->permission_a,$rule->permission_b]];}return$out;}
private function auditQuery(Request$r){$q=DB::table('activity_log')->leftJoin('users','users.id','=','activity_log.causer_id')->select('activity_log.id','activity_log.log_name','activity_log.description','activity_log.subject_type','activity_log.subject_id','activity_log.causer_type','activity_log.causer_id','users.name as actor','activity_log.properties','activity_log.created_at');if($r->filled('search')){$s='%'.$r->search.'%';$q->where(fn($x)=>$x->where('activity_log.description','like',$s)->orWhere('users.name','like',$s));}if($r->filled('log_name'))$q->where('activity_log.log_name',$r->log_name);if($r->filled('actor_id'))$q->where('activity_log.causer_id',$r->actor_id);return$q;}
private function safe(array$d):array{$blocked=['credential','secret','token','password','api_key','client_secret'];foreach($d as$k=>$v)if(collect($blocked)->contains(fn($x)=>str_contains(strtolower($k),$x)))$d[$k]='[REDACTED]';return$d;}
private function safeJson($value){$data=is_string($value)?json_decode($value,true):$value;if(!is_array($data))return$data;foreach($data as$k=>$v){if(preg_match('/secret|token|password|api.?key|credential/i',(string)$k))$data[$k]='[REDACTED]';elseif(is_array($v))$data[$k]=$this->safeJson($v);}return$data;}
private function integrationActivity(){return DB::table('ecosystem_integration_audits as a')->leftJoin('users as u','u.id','=','a.actor_id')->latest('a.created_at')->limit(15)->get(['a.*','u.name as actor']);}
private function integrationAudit($id,$r,$a,$b,$f){DB::table('ecosystem_integration_audits')->insert(['integration_id'=>$id,'action'=>$a,'actor_id'=>$r->user()->id,'before'=>$b?json_encode($b):null,'after'=>$f?json_encode($f):null,'created_at'=>now()]);}
private function govAudit($t,$id,$r,$a,$b,$f,$reason=null){DB::table('ecosystem_governance_audits')->insert(['entity_type'=>$t,'entity_id'=>$id,'action'=>$a,'actor_id'=>$r->user()->id,'before'=>$b?json_encode($b):null,'after'=>$f?json_encode($f):null,'reason'=>$reason,'created_at'=>now()]);}
private function permissions(Request$r):array{return['canView'=>$r->user()->hasPermission('ecosystem.modules.view'),'canManage'=>$r->user()->hasPermission('ecosystem.modules.configure'),'canExport'=>$r->user()->hasPermission('ecosystem.modules.view')];}}
